from pathlib import Path
import json,hashlib
R=Path(__file__).resolve().parent;P=R.parent/'workspace';repo=Path('/home/jake/Developer/Course_Academy')
def load(n):return json.load(open(R/n))
def save(n,x):(R/n).write_text(json.dumps(x,indent=2)+'\n')
