commands=[{'command':'PYTHONDONTWRITEBYTECODE=1 '+py+' setup_review.py','purpose':'Copy prior independent evidence; package hashes/diff; execute retained author checks on failing old and passing current copies.'},{'command':'PYTHONDONTWRITEBYTECODE=1 '+py+' audit_revision.py','purpose':'Independent complete source replay, paired scheduler proposals, exact arithmetic, controlled dependencies, rejections and relocation.'}]
for name,out in [('runner-batch','delivery-batch'),('fresh-samples','delivery-independent'),('retained-current-records','delivery-retained')]:
 commands.append({'command':f'{py} {repo}/generate/pipeline/check_delivery.py --input {name}.json --source ../source/source.json --inventory ../source/inventory.json --difficulty hard --output {out} --math-root /media/jake/SSD/EDB/math','purpose':'Actual read-only publisher filtering against captured inventory.'})
commands +=[{'command':'PYTHONDONTWRITEBYTECODE=1 '+py+' prepare_ui_checks.py','purpose':'Build independent native/UI cases from actual delivery survivors.'},{'command':str(repo/'generate/runs/current/check-engine')+' grader-input.json grader-results.json','purpose':'Native learner grader: 58 correct and 232 incorrect selections.'},{'command':f'{py} {repo}/generate/pipeline/render_preview.py --input render-records.json --output render --asset-root delivery-batch/assets --math-root /media/jake/SSD/EDB/math --limit 11','purpose':'Actual UI screenshots and HTML for five delivered records, counterfactuals and fraction replay.'},{'command':'PYTHONDONTWRITEBYTECODE=1 '+py+' decision_revision.py','purpose':'Conditional shortcuts, stage comparisons, inventory inspection and faithful conditional learner selection.'},{'command':'python3 -c \'import json,jsonschema; jsonschema.validate(json.load(open("pedagogical-variation.json")),json.load(open("/home/jake/Developer/Course_Academy/generate/pipeline/pedagogical-variation.schema.json")))\'','purpose':'Validate required pedagogical evidence contract.'},{'command':'python3 finalize_review.py','purpose':'Confirm all package files unchanged and required nonempty evidence refs.'}]
save('commands.json',commands)
a=load('source-analysis.json')
source={k:a[k] for k in ['skill','reasoning_steps','invariants','permitted_variations','source_refs']};source['evidence_paths']=['source-analysis.json','source-corrections.json','revision-diff.json']
def check(refs,details):return {'status':'passed','evidence_paths':refs,'details':details}
checks={
'source_replay':check(['source-replay-results.json','source-replays.json','source-corrections.json','preflight-reproduction.json'],'All eleven supplied banks replay with all five operations intact. q-72858 restored; documented q-130301 source arithmetic correction and inferred q-20392 completion retained. Both retained regressions fail on their original defective packages and pass current code.'),
'math':check(['independent.py','audit_revision.py','math-results.json','delivery-identity-results.json'],'Independent exact Fraction arithmetic checks every listed operation, unique correct choice and complete worked matrix across 32 fresh controls, five current batch items, five repaired retained proposals, eleven source replays, five controlled records and ten equality controls. Normalized batch records checked separately.'),
'variety':check(['scheduler-results.json','coverage.json','fresh-samples.json','shortcut-results.json','reused/coverage.json','revision-diff.json'],'New batch scheduling produces both swap and replacement winners for each of ten recognizable banks in controlled repeated proposals. Prior eligible-slot and all-nine-target coverage reused only for unchanged source/generate rules. Current repeated q-72858 group has both roles.'),
'scope':check(['source-analysis.json','scope-results.json','counterfactual-records.json'],'Variation preserves one elementary operation, a zero target, 3x3 matrix and five radio choices. Successful swaps follow the lesson\'s zero-donor rule. No added operators, response types or multi-step elimination.'),
'grading':check(['grader-input.json','grader-results.json','counterfactual-results.json'],'Actual native learner grader accepted all 58 independently determined correct selections and rejected all 232 distractors; no unresolved outcomes. All controlled pairs and normalized delivery records included. Free-entry equivalence is inapplicable to radio selection.'),
'rendering':check(['render-records.json','render/rendering.json','render-inspection.json','render/contact-sheet.jpg','ui-order-results.json'],'All eleven actual-UI cases rendered without reported errors; screenshots inspected for the exact five-item batch, relevant/irrelevant/target counterfactuals, fractions, controls and worked matrices.'),
'packaging':check(['packaging-results.json','rejection-results.json','relocated-records.json','package-before.json','package-after.json','commands.json'],'Exact Python 3.13.5, sympy 1.14.0 and mpmath 1.3.0 match manifest. Deterministic replay, batch replay, relocation, JSON-only output and invalid-input rejection pass. All package files unchanged; no external assets or database operations.'),
'decision_variation':check(['pedagogical-variation.json','decision-validation.json','shortcut-results.json','counterfactual-results.json','delivery-batch/delivery.json','delivery-independent/delivery.json','delivery-retained/delivery.json','selection-results.json','inventory-review.json','affected-inventory.json'],'Relevant matrix/target changes alter decisions and grading; irrelevant columns preserve them. Forty-three probes include 33 conditional probes. Prior sole-subtraction shortcut falls from 2/2 to 1/2 on both current batch and repaired retained stream. All 32 controls and both five-item pools survive delivery. Captured inventory and conditional learner-selection limits are explicit.')}
report={'verdict':'accepted','summary':'Both retained defects are resolved. All eight checks pass, including the exact five-item batch, native grading and actual UI rendering. No remaining demonstrated failure; package unchanged.','source_analysis':source,'checks':checks,'findings':[]}
for p in source['evidence_paths']+[p for c in checks.values() for p in c['evidence_paths']]:
 assert not Path(p).is_absolute() and (R/p).is_file() and (R/p).stat().st_size,p
assert len(checks)==8 and all(c['status']=='passed' for c in checks.values())
assert load('decision-validation.json')['schema'].startswith('passed')
assert load('render/rendering.json')['passed'] and len(load('render/rendering.json')['cases'])==11
save('review.json',report);save('result.json',report)
(R/'session-state.md').write_text('Complete: accepted. Both retained failures reproduced on defective old code and pass current. All eight checks pass; 32 independent fresh controls and exact five-item batch survive delivery; 290 native responses pass; eleven actual-UI cases inspected. Schema and nonempty evidence paths validated. Package-before.json equals package-after.json for every file. No package edits, publication, assets published or database writes. Review in review.json/result.json.\n')
print(json.dumps({'verdict':report['verdict'],'checks':8,'package_unchanged':True,'report':'review.json'}))
